using System;using System.Drawing;using System.Reflection;using System.Threading;using System.Windows.Forms;using BrieflyInstaller;
class InstallerViewTest{
 [STAThread]static int Main(){Application.EnableVisualStyles();using(var f=new SetupWindow()){bool green=false;foreach(Control c in f.Controls)if(c.BackColor.ToArgb()==Color.FromArgb(15,42,46).ToArgb())green=true;if(!green)throw new Exception("Green logo splash missing");var field=typeof(SetupWindow).GetField("openAfter",BindingFlags.Instance|BindingFlags.NonPublic);if(!((CheckBox)field.GetValue(f)).Checked)throw new Exception("Open app after setup must default on");f.Show();for(int i=0;i<35;i++){Application.DoEvents();Thread.Sleep(50);}var install=(Button)typeof(SetupWindow).GetField("install",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(f);if(!install.Visible||!install.Enabled)throw new Exception("Splash did not reveal real setup");f.Close();}Console.WriteLine("Green animated-logo splash transitions to actual setup; open-after-install defaults on. No installation performed.");return 0;}
}
